    for (const span of broken) {
      state.fx.push({ kind: 'snap', x: crate.x, y: crate.y, life: 0.5, max: 0.5 });
      say(state, 'A span parted under that load', 'warn');
      state.shake = Math.min(1, state.shake + 0.5);
