      state.shipmentLost = (state.shipmentLost ?? 0) + 1;
      state.chain = 0;
      state.lives -= 1;
      say(state, `${bay.label} bay is battened down: crate gone, ${state.lives} left`, 'bad');
      state.lostBy.shut += 1;
